package leetcode.medium;

import org.junit.Test;
import static org.junit.Assert.*;

public class OnlineStockSpanTest {

    @Test
    public void nextTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        assertEquals(1, stockSpan.next(10));
        assertEquals(1, stockSpan.next(5));
        assertEquals(4, stockSpan.next(30));
        assertEquals(1, stockSpan.next(15));
    }

    @Test
    public void calculateSpansTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] prices = {100, 80, 60, 70, 60, 75, 85};
        int[] expected = {1, 1, 1, 2, 1, 4, 6};
        assertArrayEquals(expected, stockSpan.calculateSpans(prices));
    }
}
```

This code has two test methods, `nextTest()` and `calculateSpansTest()`, which test the `next()` and `calculateSpans()` methods respectively. The `nextTest()` method tests the `next()` method with different input prices and verifies the returned spans. The `calculateSpansTest()` method tests the `calculateSpans()` method with a sample array of prices and verifies that the returned array of spans matches the expected output.
